(function(scope){
'use strict';
function create({data,state,save,esc,shell,readingBar,toast,persistenceMessage}){
 const sheets=data.methodSheets.sheets,names={micro:'微观',macro:'宏观'},kindNames={selection:'选法检测',variant:'条件变式',supplement:'补充知识检测'};
 const checkById=new Map(sheets.flatMap(sheet=>sheet.checks.map(check=>[check.id,check])));
 const progress=id=>state().methodProgress[id]||{draft:'',revealed:false,assisted:false,rating:null,round:1,at:0,history:[]};
 const stamp=(id,change)=>{const previous=progress(id);state().methodProgress[id]={...previous,...change,at:Math.max(Date.now(),previous.at+1)};save();};
 function url(sheet,mode='sheet'){return '#methods/'+sheet.subject+'/'+sheet.group+(mode==='checks'?'/checks':'');}
 function choices(subject){return `<nav class="method-topic-nav" aria-label="选择速查专题">${sheets.filter(sheet=>sheet.subject===subject).map(sheet=>`<a href="${url(sheet)}">${sheet.group} ${esc(sheet.title)}</a>`).join('')}</nav>`;}
 function render(){
  const [,subject,group,mode,checkId]=location.hash.slice(1).split('/'),sheet=sheets.find(item=>item.id===subject+'-'+group);
  if(!sheet){const chosen=names[subject]?subject:'micro';shell(`<div class="page-heading"><div><h1>作答速查与闭卷检测</h1><p>先看题干选方法，再检验换条件后能否重推。速查与检测分别进入。</p></div></div><nav class="tabs" aria-label="速查科目">${Object.entries(names).map(([key,name])=>`<a class="tab ${key===chosen?'active':''}" href="#methods/${key}" ${key===chosen?'aria-current="page"':''}>${name}</a>`).join('')}</nav><section class="paper method-index"><h2>${names[chosen]}10个专题</h2>${choices(chosen)}<p>每专题2道基础检测；另有26道补充知识检测。每天从选法与变式各1题起，有断点再加练。检测放入原有回忆、筛查或额外加练时段，不替代完整作答。</p><div class="actions"><a class="btn" href="materials/method-sheets.pdf">40页速查PDF</a><a class="btn" href="materials/method-checks.md" download>仅题目稿</a><a class="btn" href="materials/method-check-answers.md" download>参考与自查稿</a></div></section>`,'methods');return;}
  if(mode==='checks'){renderChecks(sheet);if(sheet.checks.some(check=>check.id===checkId))requestAnimationFrame(()=>{const target=document.getElementById('draft-'+checkId);target?.closest('.method-check')?.scrollIntoView({block:'start'});target?.focus({preventScroll:true});});return;}renderSheet(sheet);
 }
 function header(sheet,mode){return `<div class="method-back"><a class="btn flat" href="#methods/${sheet.subject}">全部${names[sheet.subject]}速查</a><a class="btn" href="#topics/${sheet.subject}/${sheet.group}">专题串联</a><a class="btn" href="#maps/${sheet.subject}/${sheet.group}/mind">完整知识导图</a><a class="btn ${mode==='checks'?'':'primary'}" href="${url(sheet,mode==='checks'?'sheet':'checks')}">${mode==='checks'?'回查本专题速查':'开始闭卷检测（'+sheet.checks.length+'题）'}</a></div>`;}
 function sheetPages(sheet){return `<section class="method-page" data-method-page="decision"><p class="method-folio">${names[sheet.subject]} ${sheet.group} / 选法与分支</p><h1>${esc(sheet.title)}</h1><div class="rich method-lead">${sheet.lead_html}</div><section class="method-starter"><h2>典型起笔（先核前提）</h2><div class="rich">${sheet.starter_html}</div></section><h2>从题干到第一行</h2><div class="method-decisions">${sheet.decisions.map(row=>`<article class="method-decision"><h3>${row.when_html}</h3><dl><dt>起笔</dt><dd class="rich">${row.start_html}</dd><dt>分支</dt><dd class="rich">${row.branch_html}</dd><dt>检验</dt><dd class="rich">${row.check_html}</dd></dl></article>`).join('')}</div><p class="method-footnote">编者速查，第1/2页。先重建约束与目标，再选模型；具体条件回查原题与知识节点。</p></section><section class="method-page" data-method-page="comparison"><p class="method-folio">${names[sheet.subject]} ${sheet.group} / 对照与闭卷重建</p><h2>${esc(sheet.title)}：怎样区分</h2><p class="method-table-hint">对照表可在表内左右滑动查看。</p><div class="method-table-wrap" role="region" aria-label="易混模型对照，可横向滚动" tabindex="0"><table class="method-comparison"><thead><tr><th scope="col">情形</th><th scope="col">起笔或判据</th><th scope="col">不能混用</th></tr></thead><tbody>${sheet.comparison_html.map(row=>`<tr>${row.map(cell=>`<td class="rich">${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div><h2>必须闭卷重建</h2><ol class="method-memory">${sheet.memory_html.map(text=>`<li class="rich">${text}</li>`).join('')}</ol><section class="method-return"><h2>把方法用回整题</h2><p>完整回练：${window.ExamTypes.sourceLinks(data,sheet.question_ids,{writing:true})}。这些入口为自由回练，不自动补记强化日完成。</p><p>本专题另配${sheet.checks.length}道短检测，含选法、条件变式${sheet.checks.some(check=>check.kind==='supplement')?'与补充知识检验':''}。先不看速查作答，交卷后逐项自评；隔日用新一轮复测。</p></section><details class="method-source"><summary>查看依据与范围</summary><p>${esc(data.methodSheets.editorial_note)}</p><p>本专题来源节点：${sheet.references.map(node=>`<a href="#maps/${sheet.subject}/${node.topic_id.slice(-2)}/network/${node.id}">${node.id}</a>`).join('、')}。</p><p>速查压缩常用决策；完整定义、推导与来源摘录仍在知识导图。短检测只检验所列动作，不代替完整题或陌生题能力验收。</p></details><p class="method-footnote">编者速查，第2/2页。20专题共40页；检测和原题完成度、自查与知识图自评分别记录。</p></section>`;}
 function renderSheet(sheet){shell(`<div class="method-reader">${header(sheet,'sheet')}${readingBar()}<div class="method-toolbar"><p>每专题两页：先选法，再对照和闭卷重建。</p><button class="btn" data-action="method-print">打印本专题速查</button></div><article class="paper method-sheet">${sheetPages(sheet)}</article></div>`,'methods');}
 function renderChecks(sheet){
  const rated=sheet.checks.filter(check=>progress(check.id).rating!==null).length;
  shell(`<div class="method-reader method-check-reader">${header(sheet,'checks')}${readingBar()}<div class="page-heading"><div><h1>${names[sheet.subject]}${sheet.group}：闭卷选法与变式检测</h1><p>先独立写条件、起式和结论，再交卷核对。已看过速查或参考时用于熟题复现；隔日再遮住重测。</p></div></div><p class="method-print-controls"><button class="btn" data-action="method-print">打印本专题检测（仅题目）</button></p><div class="method-check-summary" role="status">本专题最近自评 ${rated}/${sheet.checks.length}题。检测不计原专项、综合题或限时卷完成，也不自动更新知识图三层自评。</div><p class="small muted">每天先做选法、变式各1题，补充题按断点选做。草稿、参考展开和最近20轮自评随备份保存。</p><div class="method-checks">${sheet.checks.map(check=>{
   const item=progress(check.id),current=item.history.find(entry=>entry.round===item.round);
   return `<article class="paper method-check" data-method-check="${check.id}"><p class="method-check-kind">${check.id} · ${kindNames[check.kind]}</p><h2>${kindNames[check.kind]}${check.kind==='supplement'?'：'+esc(data.conceptMaps[sheet.subject].nodes.find(node=>node.id===check.node_ids[0]).title):''}</h2><div class="rich method-prompt">${check.prompt_html}</div><div class="method-print-space" aria-hidden="true">作答区</div><label for="draft-${check.id}">我的条件、起式与结论</label><textarea id="draft-${check.id}" data-method-draft="${check.id}" maxlength="20000" rows="5" placeholder="先闭卷写；暂时不会也可以交卷，核对最早的断点。">${esc(item.draft)}</textarea><p class="small muted" data-server-save-label data-method-save="${check.id}">${persistenceMessage()}</p><div class="actions"><button class="btn primary" data-action="method-reveal" data-id="${check.id}" ${item.revealed?'hidden':''}>交卷核对</button><button class="btn" data-action="method-reset" data-id="${check.id}" ${item.revealed?'':'hidden'}>开始新一轮闭卷</button></div><section class="method-feedback" id="feedback-${check.id}" ${item.revealed?'':'hidden'}><h3 tabindex="-1">参考推导与自查</h3><div class="rich method-answer">${check.answer_html}</div><ol>${check.criteria.map(text=>`<li>${esc(text)}</li>`).join('')}</ol><p class="small muted">${item.assisted?'本轮核对后改写过草稿，标记为订正。':'请保守自评，并自行区分是否事先见过参考。'}${current?' 本轮已自评。':''}</p><div class="method-ratings" role="group" aria-label="${check.id}自评">${[[0,'不会，需重学'],[1,'有断点，需复测'],[2,'能完整复现']].map(([rating,label])=>`<button class="btn ${item.rating===rating?'primary':''}" aria-pressed="${item.rating===rating}" data-action="method-rate" data-id="${check.id}" data-rating="${rating}">${label}</button>`).join('')}</div><p class="small muted">来源节点：${check.node_ids.map(id=>{const node=data.conceptMaps[sheet.subject].nodes.find(node=>node.id===id);return `<a href="#maps/${sheet.subject}/${node.topic_id.slice(-2)}/network/${id}">${id}</a>`;}).join('、')}。参考为编者推导，核对后应遮住重写。</p></section>${item.history.length?`<details class="method-history"><summary>最近${item.history.length}轮自评</summary><ul>${[...item.history].reverse().map(entry=>`<li>第${entry.round}轮：${['不会','有断点','能完整复现'][entry.rating]}${entry.assisted?'（核对后订正）':''}，${new Date(entry.at).toLocaleString('zh-CN')}</li>`).join('')}</ul></details>`:''}</article>`;
  }).join('')}</div></div>`,'methods');
 }
 function input(event){const id=event.target.dataset.methodDraft;if(!checkById.has(id))return false;const item=progress(id);stamp(id,{draft:event.target.value,assisted:item.assisted||item.revealed,rating:item.revealed?null:item.rating});document.querySelector('[data-method-save="'+id+'"]').textContent=persistenceMessage();if(item.revealed){const area=event.target.closest('.method-check');for(const button of area.querySelectorAll('.method-ratings button')){button.classList.remove('primary');button.setAttribute('aria-pressed','false');}const note=area.querySelector('.method-feedback>.small.muted');if(note)note.textContent='本轮核对后改写过草稿，标记为订正；请重新自评。';}return true;}
 function action(button){const name=button.dataset.action;if(!name.startsWith('method-'))return false;if(name==='method-print'){window.print();return true;}const id=button.dataset.id;if(!checkById.has(id))return true;const item=progress(id);
  if(name==='method-reveal')stamp(id,{revealed:true});
  else if(name==='method-rate'&&item.revealed){const rating=Number(button.dataset.rating);if(![0,1,2].includes(rating))return true;const at=Math.max(Date.now(),item.at+1),history=[...item.history.filter(entry=>entry.round!==item.round),{round:item.round,rating,at,assisted:item.assisted}].slice(-20);stamp(id,{rating,history});toast('已记录检测自评；不计原题完成。');}
  else if(name==='method-reset')stamp(id,{draft:'',revealed:false,assisted:false,rating:null,round:Math.min(100000,item.round+1)});
  else return true;
  const scroll=window.scrollY;render();window.scrollTo({top:scroll});const target=document.querySelector(name==='method-reveal'?'#feedback-'+id+' h3':name==='method-reset'?'#draft-'+id:'[data-method-check="'+id+'"] [data-rating="'+button.dataset.rating+'"]');target?.focus({preventScroll:true});return true;
 }
 return{render,input,action,sheetPages};
}
scope.MethodSheets={create};
})(globalThis);
